<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Exclusive Sellers Log-in | Big Ass Motors</title>
<style>
.portal-card{background:#fff;border:1px solid #e7e7e7;border-radius:12px;padding:26px}
.field{display:flex;flex-direction:column;gap:5px;margin-bottom:12px}
.btn{display:inline-block;border:0;border-radius:8px;padding:11px 14px;font-weight:700}
.btn-yellow{background:#ffc107;color:#111}
.btn-lg{padding:15px 24px;font-size:16px}
</style>
</head>
<body>
<main>
<section class="page-head"><div class="wrap"><div class="eyebrow">Exclusive Sellers</div><h1 class="h1">Exclusive Sellers Log-in</h1></div></section>
<div class="wrap two-col">
  <div class="portal-card">
    <form method="post"><input type="hidden" name="_csrf" value="test-csrf">
      <div class="field"><label>E-mail</label><input type="email" name="email" required autocomplete="email" value=""></div>
      <div class="field"><label>Password</label><input type="password" name="password" required autocomplete="current-password"></div>
      <button class="btn btn-yellow btn-lg">Log in</button>
    </form>
    <p class="muted">Forgot your password? Call 904-767-5232.</p>
  </div>
</div>
</main>
</body>
</html>
